head.b:skin:
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #f8fafc;
  --surface: #ffffff;
  --surface-hover: #f1f5f9;
  --text: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --brand: #2563eb;
  --brand-hover: #1d4ed8;
  --card-radius: 14px;
  --shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.05);
  --shadow-card: 0 4px 18px rgba(15, 23, 42, 0.06);
  --shadow-hover: 0 12px 28px rgba(15, 23, 42, 0.12);
}

body.dark-mode {
  --bg: #090d16;
  --surface: #111827;
  --surface-hover: #1f2937;
  --text: #f8fafc;
  --text-muted: #94a3b8;
  --border: #1f2937;
  --brand: #3b82f6;
  --brand-hover: #60a5fa;
  --shadow-card: 0 4px 18px rgba(0, 0, 0, 0.4);
  --shadow-hover: 0 12px 28px rgba(0, 0, 0, 0.6);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-bottom: 75px;
}

a { color: inherit; text-decoration: none; }

@keyframes srPulse {
  0%, 100% { opacity: 0.95; }
  50% { opacity: 0.35; }
}

/* Top Strip */
.top-strip {
  background: #0f172a;
  color: #93c5fd;
  text-align: center;
  padding: 8px 14px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.3px;
}

/* Minimal Modern Header */
.saas-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}
.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  flex-wrap: wrap;
}
.brand-logo {
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -0.5px;
  color: var(--brand);
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.nav-btn {
  padding: 7px 13px;
  font-size: 13px;
  font-weight: 700;
  border-radius: 8px;
  background: var(--surface-hover);
  color: var(--text-muted);
  transition: all 0.15s ease;
}
.nav-btn:hover, .nav-btn.active {
  background: var(--brand);
  color: #ffffff !important;
}
.nav-btn-highlight {
  background: var(--brand) !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}
.theme-toggle-btn {
  background: var(--surface-hover);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
}

/* Hero Search Area */
.hero-search-area {
  background: linear-gradient(135deg, #1e3a8a 0%, #0f172a 100%);
  padding: 38px 20px 32px 20px;
  text-align: center;
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.search-box-wrapper {
  max-width: 650px;
  margin: 0 auto;
  position: relative;
}
.search-input {
  width: 100%;
  padding: 15px 48px 15px 22px;
  font-size: 15px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: #ffffff;
  color: #0f172a;
  outline: none;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}
.search-input:focus {
  box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.4);
}
.search-icon {
  position: absolute;
  right: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 18px;
  color: #64748b;
}
.search-dropdown {
  position: absolute;
  top: 105%;
  left: 0;
  right: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow-hover);
  max-height: 350px;
  overflow-y: auto;
  z-index: 9999;
  display: none;
  list-style: none;
  text-align: left;
}
.search-dropdown li {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--text);
}
.search-dropdown li:hover { background: var(--surface-hover); }

/* Filter Chips Bar */
.filter-chips-container {
  max-width: 820px;
  margin: 18px auto 0 auto;
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: center;
}
.filter-chips-container::-webkit-scrollbar { display: none; }
@media (max-width: 768px) {
  .filter-chips-container { justify-content: flex-start; }
}
.chip-btn {
  padding: 7px 16px;
  border-radius: 20px;
  font-size: 12.5px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #ffffff;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}
.chip-btn:hover, .chip-btn.active {
  background: #ffffff;
  color: #0f172a !important;
  border-color: #ffffff;
}

/* Main Container & Modern Card Alignment */
.main-container {
  max-width: 1200px;
  margin: 25px auto 40px auto;
  padding: 0 16px;
  min-height: 550px;
}

.cards-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 24px;
  align-items: start;
}
.cards-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-bottom: 30px;
  align-items: start;
}
/* Mobile-First Reordering */
@media (max-width: 860px) {
  .cards-grid-3 {
    display: flex !important;
    flex-direction: column !important;
  }
  .card-order-job { order: 1 !important; }
  .card-order-adm { order: 2 !important; }
  .card-order-res { order: 3 !important; }
}

.feed-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.feed-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: #cbd5e1;
}

.card-head {
  padding: 13px 18px;
  border-bottom: 1px solid var(--border);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.3px;
  background: var(--surface);
}
.head-res { border-top: 4px solid #dc2626; color: #dc2626; }
.head-adm { border-top: 4px solid #2563eb; color: #2563eb; }
.head-job { border-top: 4px solid #16a34a; color: #16a34a; }
.head-key { border-top: 4px solid #9333ea; color: #9333ea; }
.head-syl { border-top: 4px solid #ea580c; color: #ea580c; }

.card-body-list {
  list-style: none;
  padding: 10px 14px;
  min-height: 270px;
  flex-grow: 1;
}
.card-body-list li {
  padding: 9px 8px;
  border-bottom: 1px solid #f1f5f9;
  font-size: 13.5px;
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  transition: background 0.15s ease;
}
body.dark-mode .card-body-list li { border-bottom-color: #1e293b; }
.card-body-list li:hover { background: var(--surface-hover); border-radius: 6px; }

/* Department Badges */
.org-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  white-space: nowrap;
  margin-top: 2px;
  flex-shrink: 0;
}
.badge-ssc { background: #dbeafe; color: #1e40af; }
.badge-rrb { background: #dcfce7; color: #166534; }
.badge-police { background: #fef3c7; color: #92400e; }
.badge-bank { background: #f3e8ff; color: #6b21a8; }
.badge-upsc { background: #fee2e2; color: #991b1b; }
.badge-default { background: #f1f5f9; color: #475569; }

body.dark-mode .badge-ssc { background: #1e3a8a; color: #bfdbfe; }
body.dark-mode .badge-rrb { background: #14532d; color: #bbf7d0; }
body.dark-mode .badge-police { background: #78350f; color: #fde68a; }
body.dark-mode .badge-bank { background: #581c87; color: #e9d5ff; }
body.dark-mode .badge-upsc { background: #7f1d1d; color: #fecaca; }
body.dark-mode .badge-default { background: #334155; color: #cbd5e1; }

.urgency-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 3px;
  margin-left: 6px;
  white-space: nowrap;
}
.urgency-ending { background: #fee2e2; color: #b91c1c; border: 1px solid #fca5a5; }

.card-footer-box {
  padding: 10px 18px;
  border-top: 1px solid var(--border);
  background: var(--surface-hover);
  text-align: right;
}
.btn-more-link {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--brand);
}
.btn-more-link:hover { text-decoration: underline; }

/* Centered Age Calculator Frame */
.calc-container {
  max-width: 820px;
  margin: 35px auto;
  padding: 26px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-card);
  text-align: center;
}
.calc-title {
  font-size: 20px;
  font-weight: 800;
  margin-bottom: 6px;
  color: var(--text);
}
.calc-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 22px;
}
.calc-fields {
  display: flex;
  gap: 15px;
  align-items: flex-end;
  flex-wrap: wrap;
  justify-content: center;
}
.field-box {
  flex: 1;
  min-width: 220px;
  text-align: left;
}
.field-box label {
  display: block;
  font-size: 12.5px;
  font-weight: 700;
  margin-bottom: 6px;
  color: var(--text);
}
.field-box input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: 8px;
  font-size: 14px;
  outline: none;
}
.field-box input:focus { border-color: var(--brand); }
.btn-calculate {
  background: var(--brand);
  color: #ffffff;
  padding: 11px 22px;
  font-size: 14px;
  font-weight: 700;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease;
}
.btn-calculate:hover { background: var(--brand-hover); }

/* Single Post & Static Content */
.content-card-box {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  padding: 28px;
  margin: 20px auto;
  max-width: 950px;
  box-shadow: var(--shadow-sm);
}
.content-title {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 15px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 12px;
  color: var(--brand);
}
.content-body-area {
  font-size: 15px;
  line-height: 1.8;
  color: var(--text);
}
.content-body-area table {
  width: 100%;
  border-collapse: collapse;
  margin: 20px 0;
}
.content-body-area th, .content-body-area td {
  border: 1px solid var(--border);
  padding: 10px 14px;
}
.content-body-area th { background: var(--surface-hover); }

/* Mobile App Bottom Floating Dock */
.mobile-dock {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--surface);
  border-top: 1px solid var(--border);
  box-shadow: 0 -4px 15px rgba(0, 0, 0, 0.08);
  z-index: 999;
  padding: 7px 12px;
  justify-content: space-around;
  align-items: center;
}
@media (max-width: 768px) {
  .mobile-dock { display: flex; }
}
.dock-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
}
.dock-tab:hover, .dock-tab.active { color: var(--brand); }
.dock-icon { font-size: 18px; }

/* Footer Centered Clean Alignment */
.saas-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  text-align: center;
  padding: 30px 15px;
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 50px;
}
.saas-footer a {
  color: var(--text-muted);
  margin: 0 10px;
  font-weight: 600;
}
.saas-footer a:hover { color: var(--brand); }

div.script:
//
document.addEventListener('DOMContentLoaded', function() {
  const btn = document.getElementById('calcAgeBtn');
  if (btn) {
    btn.addEventListener('click', function() {
      const dobVal = document.getElementById('calcDob').value;
      const cutoffVal = document.getElementById('calcCutoff').value;
      const resultBox = document.getElementById('calcResultDisplay');
      const resultText = document.getElementById('calcResultText');

      if (!dobVal || !cutoffVal) {
        alert('Kripya Date of Birth aur Cut-off Date dono select karein.');
        return;
      }

      const birthDate = new Date(dobVal);
      const targetDate = new Date(cutoffVal);

      if (birthDate > targetDate) {
        alert('Date of Birth cut-off date se pehle ki honi chahiye.');
        return;
      }

      let years = targetDate.getFullYear() - birthDate.getFullYear();
      let months = targetDate.getMonth() - birthDate.getMonth();
      let days = targetDate.getDate() - birthDate.getDate();

      if (days < 0) {
        months--;
        const prevMonth = new Date(targetDate.getFullYear(), targetDate.getMonth(), 0);
        days += prevMonth.getDate();
      }

      if (months < 0) {
        years--;
        months += 12;
      }

      resultText.innerText = years + ' Saal, ' + months + ' Mahine, ' + days + ' Din';
      resultBox.style.display = 'block';
    });
  }
});
//

body.script:
//
var globalAllPosts = [];
var rawFeedEntries = [];

// 1. High-Performance Client-Side Caching (0ms Instant Load)
function getCache(key) {
  try {
    var raw = sessionStorage.getItem(key);
    if (!raw) return null;
    var parsed = JSON.parse(raw);
    if (Date.now() - parsed.ts < 300000) { // 5-minute validity
      return parsed.val;
    }
  } catch(e) {}
  return null;
}

function setCache(key, val) {
  try {
    sessionStorage.setItem(key, JSON.stringify({ ts: Date.now(), val: val }));
  } catch(e) {}
}

// 2. Animated Skeleton Preloaders (Prevents blank white box effect)
function injectSkeletons() {
  var lists = ['list-result', 'list-admit', 'list-job', 'list-key', 'list-syl'];
  var skelHtml = '';
  for (var i = 0; i < 6; i++) {
    skelHtml += '<li style="padding:10px 4px; display:flex; align-items:center; gap:8px;">' +
                '<span style="display:inline-block; width:45px; height:20px; background:#e2e8f0; border-radius:4px; animation:srPulse 1.2s infinite ease-in-out;"></span>' +
                '<span style="display:inline-block; width:' + (60 + (i % 4) * 10) + '%; height:16px; background:#f1f5f9; border-radius:4px; animation:srPulse 1.2s infinite ease-in-out;"></span>' +
                '</li>';
  }
  lists.forEach(function(id) {
    var el = document.getElementById(id);
    if (el && el.children.length === 0) {
      el.innerHTML = skelHtml;
    }
  });
}

// Helper: Normalize Path for exact URL comparison
function normalizePath(u) {
  if (!u) return '';
  try {
    var parsed = new URL(u, window.location.origin);
    return parsed.pathname.toLowerCase().replace(/\/+$/, '');
  } catch(e) {
    return u.toLowerCase().split('?')[0].replace(/\/+$/, '');
  }
}

// Resizer Tool Page Visibility
(function checkResizerPage() {
  if (window.location.pathname.indexOf('/p/photo-signature-resizer') !== -1) {
    var rBox = document.getElementById('resizer-tool-wrapper');
    if (rBox) rBox.style.display = 'block';
  }
})();

// 3. Theme Controller (Dark Mode)
function applySavedTheme() {
  try {
    var saved = localStorage.getItem('sr_dark_mode');
    var body = document.body;
    var icon = document.getElementById('theme-icon');
    if (saved === 'enabled') {
      body.classList.add('dark-mode');
      if (icon) icon.innerText = '☀️';
    } else {
      body.classList.remove('dark-mode');
      if (icon) icon.innerText = '🌙';
    }
  } catch(e) {}
}

function toggleTheme() {
  var body = document.body;
  var isDark = body.classList.contains('dark-mode');
  localStorage.setItem('sr_dark_mode', isDark ? 'disabled' : 'enabled');
  applySavedTheme();
}
applySavedTheme();

// 4. Age Calculator Anchor Scroll Handler
function handleAgeCalculator(e) {
  if (window.location.pathname === '/' || window.location.pathname === '') {
    var el = document.getElementById('ageCalculator');
    if (el) {
      e.preventDefault();
      el.scrollIntoView({ behavior: 'smooth' });
    }
  }
}

// 5. Smart Badge & Department Detection
function getSmartBadges(title) {
  var t = title.toUpperCase();
  var org = '';
  var urgency = '';

  if (t.indexOf('SSC') > -1) org = '<span class="org-badge badge-ssc">SSC</span>';
  else if (t.indexOf('RAILWAY') > -1 || t.indexOf('RRB') > -1) org = '<span class="org-badge badge-rrb">RRB</span>';
  else if (t.indexOf('POLICE') > -1 || t.indexOf('CONSTABLE') > -1) org = '<span class="org-badge badge-police">POLICE</span>';
  else if (t.indexOf('BANK') > -1 || t.indexOf('IBPS') > -1 || t.indexOf('SBI') > -1) org = '<span class="org-badge badge-bank">BANK</span>';
  else if (t.indexOf('UPSC') > -1) org = '<span class="org-badge badge-upsc">UPSC</span>';
  else org = '<span class="org-badge badge-default">GOVT</span>';

  if (t.indexOf('LAST DATE') > -1 || t.indexOf('ENDING') > -1) {
    urgency = '<span class="urgency-badge urgency-ending">⏳ Ending Soon</span>';
  }
  return { org: org, urgency: urgency };
}

// 6. Interactive Quick Filter Chips Handler
window.filterFeed = function(tag, btnEl) {
  document.querySelectorAll('.chip-btn').forEach(function(b) { b.classList.remove('active'); });
  if (btnEl) btnEl.classList.add('active');
  renderHomepageBoxes(tag);
};

function renderHomepageBoxes(filterTag) {
  var resList = document.getElementById('list-result');
  var admList = document.getElementById('list-admit');
  var jobList = document.getElementById('list-job');
  var keyList = document.getElementById('list-key');
  var sylList = document.getElementById('list-syl');

  if (!resList || !admList || !jobList) return;

  var resHtml = '', admHtml = '', jobHtml = '', keyHtml = '', sylHtml = '';
  var cRes = 0, cAdm = 0, cJob = 0, cKey = 0, cSyl = 0;

  rawFeedEntries.forEach(function(p) {
    var tl = p.title.toUpperCase();

    if (filterTag && filterTag !== 'ALL') {
      if (filterTag === 'SSC' && tl.indexOf('SSC') === -1) return;
      if (filterTag === 'RAILWAY' && tl.indexOf('RAILWAY') === -1 && tl.indexOf('RRB') === -1) return;
      if (filterTag === 'POLICE' && tl.indexOf('POLICE') === -1 && tl.indexOf('CONSTABLE') === -1) return;
      if (filterTag === 'BANK' && tl.indexOf('BANK') === -1 && tl.indexOf('IBPS') === -1 && tl.indexOf('SBI') === -1) return;
      if (filterTag === '10TH' && tl.indexOf('10TH') === -1 && tl.indexOf('12TH') === -1 && tl.indexOf('INTER') === -1 && tl.indexOf('MATRIC') === -1) return;
    }

    var badges = getSmartBadges(p.title);
    var item = '<li>' + badges.org + 
               '<a href="' + p.link + '">' + p.title + '</a>' + 
               badges.urgency + '</li>';

    if (p.cat === 'Answer Key') {
      if (cKey < 15) { keyHtml += item; cKey++; }
    } else if (p.cat === 'Syllabus') {
      if (cSyl < 15) { sylHtml += item; cSyl++; }
    } else if (p.cat === 'Result') {
      if (cRes < 20) { resHtml += item; cRes++; }
    } else if (p.cat === 'Admit Card') {
      if (cAdm < 20) { admHtml += item; cAdm++; }
    } else {
      if (cJob < 20) { jobHtml += item; cJob++; }
    }
  });

  resList.innerHTML = resHtml || '<li style="color:#64748b;">No updates found.</li>';
  admList.innerHTML = admHtml || '<li style="color:#64748b;">No updates found.</li>';
  jobList.innerHTML = jobHtml || '<li style="color:#64748b;">No updates found.</li>';
  if (keyList) keyList.innerHTML = keyHtml || '<li style="color:#64748b;">No updates found.</li>';
  if (sylList) sylList.innerHTML = sylHtml || '<li style="color:#64748b;">No updates found.</li>';
}

// 7. Live Search Engine
function setupLiveSearch() {
  var input = document.getElementById('site-search-input');
  var list = document.getElementById('search-results-list');
  if (!input || !list) return;

  input.addEventListener('input', function() {
    var query = this.value.trim().toLowerCase();
    if (query.length < 2) {
      list.style.display = 'none';
      list.innerHTML = '';
      return;
    }

    var matched = [];
    for (var i = 0; i < globalAllPosts.length; i++) {
      var p = globalAllPosts[i];
      if (p.title.toLowerCase().indexOf(query) > -1) {
        matched.push(p);
        if (matched.length >= 8) break;
      }
    }

    if (matched.length > 0) {
      var html = '';
      for (var j = 0; j < matched.length; j++) {
        var catLabel = matched[j].cat ? '<span class="org-badge badge-ssc">' + matched[j].cat + '</span>' : '';
        html += '<li><a href="' + matched[j].link + '">' + catLabel + matched[j].title + '</a></li>';
      }
      list.innerHTML = html;
      list.style.display = 'block';
    } else {
      list.innerHTML = '<li style="color:#64748b;text-align:center;">No matching vacancy found</li>';
      list.style.display = 'block';
    }
  });

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.search-box-wrapper')) {
      list.style.display = 'none';
    }
  });
}

// 8. MAIN PORTAL CONTROLLER
(function() {
  var currentPath = normalizePath(window.location.pathname);
  var isSinglePost = currentPath.indexOf('.html') > -1 && currentPath.indexOf('/p/') === -1;
  var isStaticPage = currentPath.indexOf('/p/') > -1 && currentPath.indexOf('photo-signature-resizer') === -1;
  var isLabelPage = window.location.pathname.indexOf('/search/label/') > -1;

  // STATIC PAGES (About, Disclaimer, Privacy Policy)
  if (isStaticPage) {
    var directBox = document.getElementById('direct-post-display');
    var cachedPage = getCache('page_' + currentPath);
    if (cachedPage && directBox) {
      directBox.innerHTML = cachedPage;
      setupLiveSearch();
      return;
    }

    fetch('/feeds/pages/default?alt=json')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var entries = data.feed.entry || [];
        var matched = null;
        for (var i = 0; i < entries.length; i++) {
          var links = entries[i].link || [];
          for (var j = 0; j < links.length; j++) {
            if (links[j].rel === 'alternate' && normalizePath(links[j].href) === currentPath) {
              matched = entries[i];
              break;
            }
          }
          if (matched) break;
        }

        if (matched && directBox) {
          var pTitle = matched.title ? matched.title.$t : '';
          var pContent = matched.content ? matched.content.$t : (matched.summary ? matched.summary.$t : '');
          var rendered = '<div class="content-card-box">' +
                         '<h1 class="content-title">' + pTitle + '</h1>' +
                         '<div class="content-body-area">' + pContent + '</div>' +
                         '</div>';
          directBox.innerHTML = rendered;
          setCache('page_' + currentPath, rendered);
        }
      })
      .catch(function() {});
    setupLiveSearch();
    return;
  }

  // SINGLE POST LOADER (INSTANT 0ms CACHE + LIGHTWEIGHT DIRECT QUERY)
  if (isSinglePost) {
    var directBox = document.getElementById('direct-post-display');
    var cachedPost = getCache('post_' + currentPath);

    // Instant Render from Local Session Cache (0ms)
    if (cachedPost && directBox) {
      directBox.innerHTML = cachedPost;
      setupLiveSearch();
      return;
    }

    // Animated pulse shimmer while fetching post
    if (directBox) {
      directBox.innerHTML = '<div class="content-card-box" style="padding:24px;">' +
                            '<div style="height:32px; width:70%; background:#e2e8f0; border-radius:6px; margin-bottom:16px; animation:srPulse 1.2s infinite;"></div>' +
                            '<div style="height:18px; width:95%; background:#f1f5f9; border-radius:4px; margin-bottom:8px; animation:srPulse 1.2s infinite;"></div>' +
                            '<div style="height:18px; width:85%; background:#f1f5f9; border-radius:4px; margin-bottom:24px; animation:srPulse 1.2s infinite;"></div>' +
                            '<div style="height:140px; width:100%; background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; animation:srPulse 1.2s infinite;"></div>' +
                            '</div>';
    }

    function searchFeed(maxResults) {
      return fetch('/feeds/posts/default?alt=json&max-results=' + maxResults)
        .then(function(res) { return res.json(); })
        .then(function(data) {
          var entries = data.feed.entry || [];
          var matched = null;
          for (var i = 0; i < entries.length; i++) {
            var links = entries[i].link || [];
            for (var j = 0; j < links.length; j++) {
              if (links[j].rel === 'alternate' && normalizePath(links[j].href) === currentPath) {
                matched = entries[i];
                break;
              }
            }
            if (matched) break;
          }
          return matched;
        });
    }

    searchFeed(40).then(function(matched) {
      if (!matched) {
        return searchFeed(250);
      }
      return matched;
    }).then(function(matched) {
      if (matched && directBox) {
        var pTitle = matched.title ? matched.title.$t : '';
        var pContent = matched.content ? matched.content.$t : (matched.summary ? matched.summary.$t : '');
        var rendered = '<div class="content-card-box">' +
                       '<h1 class="content-title">' + pTitle + '</h1>' +
                       '<div class="content-body-area">' + pContent + '</div>' +
                       '</div>';
        directBox.innerHTML = rendered;
        setCache('post_' + currentPath, rendered);
      }
    }).catch(function() {});

    setupLiveSearch();
    return;
  }

  // LABEL ARCHIVE LOADER (LIGHTWEIGHT SUMMARY FEED)
  if (isLabelPage) {
    var rawCat = window.location.pathname.split('/search/label/')[1].split('?')[0];
    var catName = decodeURIComponent(rawCat).replace(/\+/g, ' ').trim();
    var catNameLower = catName.toLowerCase();

    var catContainer = document.getElementById('category-view-container');
    var catTitle = document.getElementById('archive-category-title');
    var itemsList = document.getElementById('archive-items-list');
    var paginationBox = document.getElementById('archive-pagination');

    if (catContainer) catContainer.style.display = 'block';
    if (catTitle) catTitle.innerText = catName + ' - All Updates';

    var allFilteredPosts = [];
    var perPage = 30;

    fetch('/feeds/posts/summary?alt=json&max-results=200')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var raw = data.feed.entry || [];
        globalAllPosts = [];

        raw.forEach(function(entry) {
          var t = (entry.title.$t || '').trim();
          var tl = t.toLowerCase();
          if (t.length < 15) return;

          var l = '#';
          for (var j = 0; j < (entry.link || []).length; j++) {
            if (entry.link[j].rel === 'alternate') { l = entry.link[j].href; break; }
          }

          var cats = (entry.category || []).map(function(c) {
            return (c.term || '').toLowerCase().trim();
          });

          var primaryCat = 'Job';
          if (cats.indexOf('answer key') > -1 || tl.indexOf('answer key') > -1) primaryCat = 'Answer Key';
          else if (cats.indexOf('syllabus') > -1 || tl.indexOf('syllabus') > -1) primaryCat = 'Syllabus';
          else if (cats.indexOf('result') > -1 || tl.indexOf('result') > -1) primaryCat = 'Result';
          else if (cats.indexOf('admit card') > -1 || tl.indexOf('admit card') > -1 || tl.indexOf('exam date') > -1) primaryCat = 'Admit Card';

          globalAllPosts.push({ title: t, link: l, cat: primaryCat });

          var isMatch = false;
          if (cats.indexOf(catNameLower) > -1) isMatch = true;
          else if (catNameLower === 'latest jobs' && (primaryCat === 'Job' || tl.indexOf('online form') > -1 || tl.indexOf('recruitment') > -1)) isMatch = true;
          else if (catNameLower === 'result' && (primaryCat === 'Result' || tl.indexOf('result') > -1)) isMatch = true;
          else if (catNameLower === 'admit card' && (primaryCat === 'Admit Card' || tl.indexOf('admit') > -1)) isMatch = true;
          else if (catNameLower === 'answer key' && (primaryCat === 'Answer Key' || tl.indexOf('answer key') > -1)) isMatch = true;
          else if (catNameLower === 'syllabus' && (primaryCat === 'Syllabus' || tl.indexOf('syllabus') > -1)) isMatch = true;

          if (isMatch) allFilteredPosts.push({ title: t, link: l });
        });

        renderArchivePage(1);
        setupLiveSearch();
      });

    function renderArchivePage(page) {
      var total = allFilteredPosts.length;
      var totalPages = Math.ceil(total / perPage) || 1;
      var start = (page - 1) * perPage;
      var end = Math.min(start + perPage, total);

      var listHtml = '';
      for (var i = start; i < end; i++) {
        var badges = getSmartBadges(allFilteredPosts[i].title);
        listHtml += '<li style="padding:10px 4px; border-bottom:1px solid var(--border); display:flex; align-items:center; gap:8px;">' +
                    badges.org +
                    '<a href="' + allFilteredPosts[i].link + '" style="font-weight:600;">' + allFilteredPosts[i].title + '</a>' +
                    badges.urgency + '</li>';
      }
      if (itemsList) itemsList.innerHTML = listHtml || '<li>No records found in this category.</li>';

      var pagHtml = '';
      if (totalPages > 1) {
        pagHtml += '<button ' + (page === 1 ? 'disabled' : '') + ' onclick="window._goCatPage(' + (page - 1) + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:4px; background:var(--surface); cursor:pointer;">« Prev</button>';
        for (var p = 1; p <= totalPages; p++) {
          if (p === 1 || p === totalPages || (p >= page - 2 && p <= page + 2)) {
            pagHtml += '<button class="' + (p === page ? 'active' : '') + '" onclick="window._goCatPage(' + p + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:4px; background:' + (p === page ? 'var(--brand)' : 'var(--surface)') + '; color:' + (p === page ? '#fff' : 'inherit') + '; cursor:pointer;">' + p + '</button>';
          }
        }
        pagHtml += '<button ' + (page === totalPages ? 'disabled' : '') + ' onclick="window._goCatPage(' + (page + 1) + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:4px; background:var(--surface); cursor:pointer;">Next »</button>';
      }
      if (paginationBox) paginationBox.innerHTML = pagHtml;
    }

    window._goCatPage = function(p) {
      renderArchivePage(p);
      window.scrollTo({ top: 120, behavior: 'smooth' });
    };
    return;
  }

  // HOMEPAGE FEED LOADER (INSTANT 0ms SESSION CACHE + 180KB SUMMARY FEED)
  if (currentPath === '' || currentPath === '/') {
    var cachedEntries = getCache('sr_home_posts');
    if (cachedEntries && cachedEntries.length > 0) {
      globalAllPosts = cachedEntries;
      rawFeedEntries = cachedEntries;
      renderHomepageBoxes('ALL');
      setupLiveSearch();
    } else {
      injectSkeletons();
    }

    var blocked = ['contact us', 'privacy policy', 'disclaimer', 'about us', 'admission', 'latest job', 'admit card', 'result', 'syllabus', 'answer key', 'sarkari result'];

    fetch('/feeds/posts/summary?alt=json&max-results=90')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var entries = data.feed.entry || [];
        var freshPosts = [];

        entries.forEach(function(entry) {
          var title = (entry.title.$t || '').trim();
          var tl = title.toLowerCase();

          for (var b = 0; b < blocked.length; b++) {
            if (tl === blocked[b] || tl === blocked[b] + '™') return;
          }
          if (title.length < 15) return;

          var link = '#';
          for (var i = 0; i < (entry.link || []).length; i++) {
            if (entry.link[i].rel === 'alternate') { link = entry.link[i].href; break; }
          }

          var cats = (entry.category || []).map(function(c) {
            return (c.term || '').toLowerCase().trim();
          });

          var primaryCat = 'Job';
          if (cats.indexOf('answer key') > -1 || tl.indexOf('answer key') > -1) primaryCat = 'Answer Key';
          else if (cats.indexOf('syllabus') > -1 || tl.indexOf('syllabus') > -1) primaryCat = 'Syllabus';
          else if (cats.indexOf('result') > -1 || tl.indexOf('result') > -1) primaryCat = 'Result';
          else if (cats.indexOf('admit card') > -1 || tl.indexOf('admit card') > -1 || tl.indexOf('exam date') > -1) primaryCat = 'Admit Card';

          freshPosts.push({ title: title, link: link, cat: primaryCat });
        });

        if (freshPosts.length > 0) {
          globalAllPosts = freshPosts;
          rawFeedEntries = freshPosts;
          setCache('sr_home_posts', freshPosts);
          renderHomepageBoxes('ALL');
        }
        setupLiveSearch();
      })
      .catch(function(err) {});
  }
})();

// 9. PHOTO & SIGNATURE RESIZER TOOL ENGINE
(function() {
  const fileIn = document.getElementById('toolImgInput');
  const wIn = document.getElementById('toolWidth');
  const hIn = document.getElementById('toolHeight');
  const kbIn = document.getElementById('toolMaxKB');
  const btn = document.getElementById('toolProcessBtn');
  const resBox = document.getElementById('toolResult');
  const prev = document.getElementById('toolPreview');
  const meta = document.getElementById('toolMeta');
  const dl = document.getElementById('toolDownload');

  let currentImg = new Image();

  if (fileIn) {
    fileIn.addEventListener('change', function(e) {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = function(evt) {
          currentImg.onload = function() {
            wIn.value = currentImg.naturalWidth;
            hIn.value = currentImg.naturalHeight;
          };
          currentImg.src = evt.target.result;
        };
        reader.readAsDataURL(file);
      }
    });
  }

  if (btn) {
    btn.addEventListener('click', function() {
      if (!currentImg.src || !fileIn.files[0]) {
        alert('Kripya pehle image file select karein.');
        return;
      }

      const targetW = parseInt(wIn.value) || currentImg.naturalWidth;
      const targetH = parseInt(hIn.value) || currentImg.naturalHeight;
      const maxKB = parseFloat(kbIn.value);

      const canvas = document.createElement('canvas');
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(currentImg, 0, 0, targetW, targetH);

      let quality = 0.92;
      let dataUrl = canvas.toDataURL('image/jpeg', quality);

      if (maxKB) {
        while (quality > 0.08) {
          const currentKB = (dataUrl.length * (3/4)) / 1024;
          if (currentKB <= maxKB) break;
          quality -= 0.08;
          dataUrl = canvas.toDataURL('image/jpeg', quality);
        }
      }

      const finalKB = ((dataUrl.length * (3/4)) / 1024).toFixed(1);
      prev.src = dataUrl;
      dl.href = dataUrl;
      meta.innerText = 'Size: ' + targetW + 'x' + targetH + ' px | File Size: ' + finalKB + ' KB';
      resBox.style.display = 'block';
    });
  }
})();

// 10. HELPER BANNER INJECTION ON POSTS
(function injectResizerBanner() {
  if (window.location.pathname === '/' || window.location.pathname.indexOf('/p/') !== -1) {
    return;
  }

  var attempts = 0;
  var interval = setInterval(function() {
    attempts++;
    var container = document.getElementById('direct-post-display') || 
                    document.querySelector('.content-body-area') || 
                    document.querySelector('.post-body');

    if (container && (container.innerText.length > 50 || container.children.length > 0)) {
      if (!document.getElementById('sr-resizer-banner')) {
        var banner = document.createElement('div');
        banner.id = 'sr-resizer-banner';
        banner.style.cssText = 'background: #eff6ff; border: 1px solid #bfdbfe; border-left: 5px solid #2563eb; padding: 14px 18px; margin: 25px auto 15px auto; border-radius: 8px; font-family: inherit; max-width: 95%; box-sizing: border-box;';
        banner.innerHTML = '<p style="margin: 0; font-size: 14px; color: #1e3a8a; line-height: 1.5;">' +
          '📌 <b>Online Form Helper:</b> Is bharti ka online form bharte waqt photo aur signature resize karne ke liye hamara ' +
          '<a href="/p/photo-signature-resizer.html" target="_blank" style="color: #2563eb; font-weight: bold; text-decoration: underline;">Online Photo &amp; Signature Resizer Tool</a> 100% Free use karein.' +
          '</p>';
        container.appendChild(banner);
      }
      clearInterval(interval);
    }

    if (attempts > 30) {
      clearInterval(interval);
    }
  }, 500);
})();
